                      tag_asset."assetId" = "still"."id"
                      and tag."isPrivate" = true
                  )
                )
            )
          )
          or exists (
            select
              1
            from
              shared_link as granted_link
              join asset as granted_asset on granted_asset."ownerId" = granted_link."userId"
              join asset as granted_target on granted_target.id = "album"."albumThumbnailAssetId"
              and granted_target."ownerId" = granted_asset."ownerId"
            where
              granted_link.id = "shared_link"."id"
              and granted_link."includePrivateAssets"
              and (
                granted_link."expiresAt" is null
                or granted_link."expiresAt" > now()
              )
              and granted_asset."deletedAt" is null
              and granted_target."deletedAt" is null
              and (
                granted_asset.id = "album"."albumThumbnailAssetId"
                or granted_asset."livePhotoVideoId" = "album"."albumThumbnailAssetId"
              )
              and (
                exists (
                  select
                    1
                  from
                    shared_link_asset as granted_membership
                  where
                    granted_membership."sharedLinkId" = granted_link.id
                    and granted_membership."assetId" = granted_asset.id
                )
                or exists (
                  select
                    1
                  from
                    album_asset as granted_membership
                    join album as granted_album on granted_album.id = granted_membership."albumId"
                  where
                    granted_membership."albumId" = granted_link."albumId"
                    and granted_membership."assetId" = granted_asset.id
                    and granted_album."deletedAt" is null
                )
              )
          )
        ) then (
          select
            candidate.id
          from
            album_asset
            join asset as candidate on candidate.id = album_asset."assetId"
          where
            album_asset."albumId" = "album"."id"
            and candidate."deletedAt" is null
            and (
              not (
                exists (
                  select
                    1
                  from
                    tag_asset
                    join tag_closure on tag_closure.id_descendant = tag_asset."tagId"
                    join tag on tag.id = tag_closure.id_ancestor
                  where
                    tag_asset."assetId" = "candidate"."id"
                    and tag."isPrivate" = true
                )
                or exists (
                  select
                    1
                  from
                    asset as private_asset
                  where
                    private_asset.id = "candidate"."id"
                    and private_asset.visibility = 'locked'
                )
                or exists (
                  select
                    1
                  from
                    asset as still
                  where
                    still."livePhotoVideoId" = "candidate"."id"
                    and (
                      still.visibility = 'locked'
                      or exists (
                        select
                          1
                        from
                          tag_asset
                          join tag_closure on tag_closure.id_descendant = tag_asset."tagId"
                          join tag on tag.id = tag_closure.id_ancestor
                        where
                          tag_asset."assetId" = "still"."id"
                          and tag."isPrivate" = true
                      )
                    )
                )
              )
              or exists (
                select
                  1
                from
                  shared_link as granted_link
                  join asset as granted_asset on granted_asset."ownerId" = granted_link."userId"
                  join asset as granted_target on granted_target.id = "candidate"."id"
                  and granted_target."ownerId" = granted_asset."ownerId"
                where
                  granted_link.id = "shared_link"."id"
                  and granted_link."includePrivateAssets"
                  and (
                    granted_link."expiresAt" is null
                    or granted_link."expiresAt" > now()
                  )
                  and granted_asset."deletedAt" is null
                  and granted_target."deletedAt" is null
                  and (
                    granted_asset.id = "candidate"."id"
                    or granted_asset."livePhotoVideoId" = "candidate"."id"
                  )
                  and (
                    exists (
                      select
                        1
                      from
                        shared_link_asset as granted_membership
                      where
                        granted_membership."sharedLinkId" = granted_link.id
                        and granted_membership."assetId" = granted_asset.id
                    )
                    or exists (
                      select
                        1
                      from
                        album_asset as granted_membership
                        join album as granted_album on granted_album.id = granted_membership."albumId"
                      where
                        granted_membership."albumId" = granted_link."albumId"
                        and granted_membership."assetId" = granted_asset.id
                        and granted_album."deletedAt" is null
                    )
                  )
              )
            )
          order by
            candidate."fileCreatedAt" desc,
            candidate.id
          limit
            1
        )
        else "album"."albumThumbnailAssetId"
      end as "visibleThumbnailAssetId",
      (
        select
          coalesce(json_agg(agg), '[]')
        from
          (
            select
              "album_user"."role",
              (
                select
                  to_json(obj)
                from
                  (
                    select
                      "id",
                      "name",
                      "email",
                      "avatarColor",
                      "profileImagePath",
                      "profileChangedAt"
                    from
                      (
                        select
                          1
                      ) as "dummy"
                  ) as obj
              ) as "user"
            from
              "album_user"
              inner join "user" on "user"."id" = "album_user"."userId"
            where
              "album_user"."role" = 'owner'
              and "album_user"."albumId" = "album"."id"
          ) as agg
      ) as "albumUsers"
    from
      "album"
    where
      "album"."id" = "shared_link"."albumId"
      and "album"."deletedAt" is null
  ) as "album" on true
where
  "shared_link"."userId" = $1
  and (
    "shared_link"."type" = 'INDIVIDUAL'
    or "album"."id" is not null
  )
  and "shared_link"."albumId" = $2
order by
  "shared_link"."createdAt" desc

-- SharedLinkRepository.getByKey
select
  "shared_link"."id",
  "shared_link"."userId",
  "shared_link"."albumId",
  "shared_link"."expiresAt",
  "shared_link"."showExif",
  "shared_link"."allowUpload",
  "shared_link"."allowDownload",
  "shared_link"."includePrivateAssets",
  "shared_link"."password",
  (
    select
      to_json(obj)
    from
      (
        select
          "user"."id",
          "user"."name",
          "user"."email",
          "user"."isAdmin",
          "user"."quotaUsageInBytes",
          "user"."quotaSizeInBytes"
        from
          "user"
        where
          "user"."id" = "shared_link"."userId"
      ) as obj
  ) as "user"
from
  "shared_link"
  left join "album" on "album"."id" = "shared_link"."albumId"
where
  "album"."deletedAt" is null
  and (
    "shared_link"."type" = $1
    or "album"."id" is not null
  )
  and "shared_link"."key" = $2

-- SharedLinkRepository.getBySlug
select
  "shared_link"."id",
  "shared_link"."userId",
  "shared_link"."albumId",
  "shared_link"."expiresAt",
  "shared_link"."showExif",
  "shared_link"."allowUpload",
  "shared_link"."allowDownload",
  "shared_link"."includePrivateAssets",
  "shared_link"."password",
  (
    select
      to_json(obj)
    from
      (
        select
          "user"."id",
          "user"."name",
          "user"."email",
          "user"."isAdmin",
          "user"."quotaUsageInBytes",
          "user"."quotaSizeInBytes"
        from
          "user"
        where
          "user"."id" = "shared_link"."userId"
      ) as obj
  ) as "user"
from
  "shared_link"
  left join "album" on "album"."id" = "shared_link"."albumId"
where
  "album"."deletedAt" is null
  and (
    "shared_link"."type" = $1
    or "album"."id" is not null
  )
  and "shared_link"."slug" = $2

-- SharedLinkRepository.getSharedLinks
select
  "shared_link".*,
  coalesce(
    json_agg("assets") filter (
      where
        "assets"."id" is not null
    ),
    '[]'
  ) as "assets"
from
  "shared_link"
  left join "shared_link_asset" on "shared_link_asset"."sharedLinkId" = "shared_link"."id"
  left join lateral (
    select
      "asset".*
    from
      "asset"
      inner join lateral (
        select
          "asset_exif"."assetId",
          "asset_exif"."autoStackId",
          "asset_exif"."bitsPerSample",
          "asset_exif"."city",
          "asset_exif"."colorspace",
          "asset_exif"."country",
          "asset_exif"."dateTimeOriginal",
          "asset_exif"."description",
          "asset_exif"."exifImageHeight",
          "asset_exif"."exifImageWidth",
          "asset_exif"."exposureTime",
          "asset_exif"."fileSizeInByte",
          "asset_exif"."fNumber",
          "asset_exif"."focalLength",
          "asset_exif"."fps",
          "asset_exif"."iso",
          "asset_exif"."latitude",
          "asset_exif"."lensModel",
          "asset_exif"."livePhotoCID",
          "asset_exif"."longitude",
          "asset_exif"."make",
          "asset_exif"."model",
          "asset_exif"."modifyDate",
          "asset_exif"."orientation",
          "asset_exif"."profileDescription",
          "asset_exif"."projectionType",
          "asset_exif"."rating",
          "asset_exif"."state",
          "asset_exif"."tags",
          "asset_exif"."timeZone"
        from
          "asset_exif"
        where
          "asset_exif"."assetId" = "asset"."id"
      ) as "exifInfo" on true
    where
      "asset"."id" = "shared_link_asset"."assetId"
      and (
        not (
          exists (
            select
              1
            from
              tag_asset
              join tag_closure on tag_closure.id_descendant = tag_asset."tagId"
              join tag on tag.id = tag_closure.id_ancestor
            where
              tag_asset."assetId" = "asset"."id"
              and tag."isPrivate" = true
          )
          or exists (
            select
              1
            from
              asset as private_asset
            where
              private_asset.id = "asset"."id"
              and private_asset.visibility = 'locked'
          )
          or exists (
            select
              1
            from
              asset as still
            where
              still."livePhotoVideoId" = "asset"."id"
              and (
                still.visibility = 'locked'
                or exists (
                  select
                    1
                  from
                    tag_asset
                    join tag_closure on tag_closure.id_descendant = tag_asset."tagId"
                    join tag on tag.id = tag_closure.id_ancestor
                  where
                    tag_asset."assetId" = "still"."id"
                    and tag."isPrivate" = true
                )
              )
          )
        )
        or exists (
          select
            1
          from
            shared_link as granted_link
            join asset as granted_asset on granted_asset."ownerId" = granted_link."userId"
            join asset as granted_target on granted_target.id = "asset"."id"
            and granted_target."ownerId" = granted_asset."ownerId"
          where
            granted_link.id = "shared_link_asset"."sharedLinkId"
            and granted_link."includePrivateAssets"
            and (
              granted_link."expiresAt" is null
              or granted_link."expiresAt" > now()
            )
            and granted_asset."deletedAt" is null
            and granted_target."deletedAt" is null
            and (
              granted_asset.id = "asset"."id"
              or granted_asset."livePhotoVideoId" = "asset"."id"
            )
            and (
              exists (
                select
                  1
                from
                  shared_link_asset as granted_membership
                where
                  granted_membership."sharedLinkId" = granted_link.id
                  and granted_membership."assetId" = granted_asset.id
              )
              or exists (
                select
                  1
                from
                  album_asset as granted_membership
                  join album as granted_album on granted_album.id = granted_membership."albumId"
                where
                  granted_membership."albumId" = granted_link."albumId"
                  and granted_membership."assetId" = granted_asset.id
                  and granted_album."deletedAt" is null
              )
            )
        )
      )
  ) as "assets" on true
where
  "shared_link"."id" = $1
group by
  "shared_link"."id"
